
from pathlib import Path
from typing import Any

import joblib
import pandas as pd
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field


ROOT = Path(__file__).resolve().parents[1]
MODEL_PATH = ROOT / "models" / "best_sales_model.joblib"

app = FastAPI(
    title="Sales Prediction API",
    description=(
        "Predict next-day sales using the trained machine-learning model. "
        "Provide the numeric features generated by the preprocessing pipeline."
    ),
    version="1.0.0",
)

artifact: dict[str, Any] | None = None
model_load_error: str | None = None

try:
    if not MODEL_PATH.exists():
        raise FileNotFoundError(
            f"Model not found at {MODEL_PATH}. "
            "Run: python -m src.train_model"
        )

    loaded = joblib.load(MODEL_PATH)

    if not isinstance(loaded, dict) or "model" not in loaded:
        raise ValueError(
            "Unexpected model artifact format. Retrain the model first."
        )

    if not loaded.get("feature_columns"):
        raise ValueError("Model artifact has no feature schema.")

    artifact = loaded

except Exception as exc:
    model_load_error = str(exc)


class PredictionRequest(BaseModel):
    features: dict[str, float] = Field(
        ...,
        description=(
            "Feature names and numeric values. Include every feature listed "
            "by GET /model-info."
        ),
        examples=[
            {
                "day_of_week": 2,
                "day_of_month": 15,
                "month": 11,
                "day_of_year": 319,
                "is_weekend": 0,
                "sales_lag_0": 45000,
                "sales_lag_1": 42000,
                "sales_lag_2": 39000,
                "sales_lag_7": 41000,
                "sales_lag_14": 38000,
                "sales_lag_28": 36000,
                "rolling_mean_7": 40000,
                "rolling_mean_14": 39500,
                "rolling_std_7": 7000,
            }
        ],
    )


def get_artifact() -> dict[str, Any]:
    if artifact is None:
        raise HTTPException(
            status_code=503,
            detail=(
                "The model is not available. Check the model artifact and "
                "run python -m src.train_model."
            ),
        )
    return artifact


@app.get("/")
def root():
    return {
        "message": "Sales Prediction API",
        "docs": "/docs",
        "health": "/health",
    }


@app.get("/health")
def health():
    if artifact is None:
        return {
            "status": "unavailable",
            "model_loaded": False,
            "error": model_load_error,
        }

    return {
        "status": "healthy",
        "model_loaded": True,
        "model_name": artifact["model_name"],
    }


@app.get("/model-info")
def model_info():
    current = get_artifact()

    return {
        "model_name": current["model_name"],
        "feature_columns": current["feature_columns"],
        "target_column": current["target_column"],
        "currency": current.get("currency", "GBP"),
        "test_metrics": current.get("test_metrics", {}),
    }


@app.post("/predict")
def predict(request: PredictionRequest):
    current = get_artifact()
    expected_features = current["feature_columns"]
    supplied_features = request.features

    missing = [
        name for name in expected_features
        if name not in supplied_features
    ]
    unexpected = [
        name for name in supplied_features
        if name not in expected_features
    ]

    if missing or unexpected:
        raise HTTPException(
            status_code=422,
            detail={
                "message": "Feature names do not match the trained model.",
                "missing_features": missing,
                "unexpected_features": unexpected,
                "expected_features": expected_features,
            },
        )

    try:
        input_frame = pd.DataFrame(
            [[supplied_features[name] for name in expected_features]],
            columns=expected_features,
        )

        prediction = float(current["model"].predict(input_frame)[0])

        return {
            "predicted_next_day_sales": round(prediction, 2),
            "currency": current.get("currency", "GBP"),
            "model_name": current["model_name"],
            "note": (
                "This is a model estimate, not a guarantee of future sales."
            ),
        }

    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail=f"Prediction failed: {exc}",
        ) from exc
